function App() {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [products] = useState([
    { id: 'product1', name: 'Produit 1', price: '0.1' },  // Prix en BNB
    { id: 'product2', name: 'Produit 2', price: '0.2' },
    { id: 'product3', name: 'Produit 3', price: '0.3' },
  ]);
  const [isConnected, setIsConnected] = useState(false);
  const [walletAddress, setWalletAddress] = useState('');

  const [provider, setProvider] = useState(null);
  const [contract, setContract] = useState(null);

  // Fonction de connexion avec MetaMask
  const connectWallet = async () => {
    const modal = new Web3Modal({
      cacheProvider: true,
      providerOptions: {
        metamask: {
          package: null,
        },
      },
    });
    const instance = await modal.connect();
    const newProvider = new ethers.providers.Web3Provider(instance);
    setProvider(newProvider);
    const signer = newProvider.getSigner();
    const address = await signer.getAddress();
    setWalletAddress(address);
    setIsConnected(true);
    const contractInstance = new ethers.Contract(contractAddress, contractABI, signer);
    setContract(contractInstance);
  };

  // Fonction pour effectuer le paiement
  const handlePayment = async () => {
    if (!selectedProduct || !contract) return;

    const priceInWei = ethers.utils.parseEther(selectedProduct.price);

    try {
      // Envoi de la transaction en BNB
      const tx = await contract.pay(
        // Aucun besoin d'indiquer l'adresse comme address(0) ici.
        ethers.constants.AddressZero, // Adresse pour BNB, donc address(0)
        priceInWei,
        selectedProduct.id,
        {
          value: priceInWei, // Nous passons le montant à payer en BNB via "value"
        }
      );
      await tx.wait();
      alert('Paiement réussi!');
    } catch (err) {
      console.error('Erreur de paiement', err);
      alert('Erreur lors du paiement. Essayez à nouveau.');
    }
  };


  return (
    <div className="App">
      <h1>Système de Paiement Multi-Produits</h1>
      {!isConnected ? (
        <button onClick={connectWallet}>Se connecter à MetaMask</button>
      ) : (
        <p>Connecté avec : {walletAddress}</p>
      )}

      <h2>Choisir un produit</h2>
      <div>
        {products.map((product) => (
          <button
            key={product.id}
            onClick={() => setSelectedProduct(product)}
            style={{ marginBottom: '10px', marginRight: '10px' }}
          >
            {product.name} - {product.price} BNB
          </button>
        ))}
      </div>

      {selectedProduct && (
        <div>
          <p>Produit sélectionné : {selectedProduct.name}</p>
          <button onClick={handlePayment}>Payer en BNB</button>
        </div>
      )}
    </div>
  );
}

export default App;
